226: #[test]
227: fn test_gimbal_modes_and_limits() {
228:     // 7-byte minimal payload: Pitch=-45.0°, Roll=10.0°, Yaw=90.0°
229:     // raw_pitch: -450 = 0xFE3E -> [0x3E, 0xFE]
230:     // raw_roll: 100 = 0x0064 -> [0x64, 0x00]
231:     // raw_yaw: 900 = 0x0384 -> [0x84, 0x03]
232:     // bitmask: 0x41 (Bit 0: Pitch limit, Bit 6: Stuck, Bits 6..7: FPV)
233:     let payload = [0x3E, 0xFE, 0x64, 0x00, 0x84, 0x03, 0x41];
234:     let gimbal = GimbalRecord::parse(&payload).expect("Must parse 7-byte Gimbal record");
235:     assert!((gimbal.pitch_deg - (-45.0)).abs() < 1e-5);
236:     assert!((gimbal.roll_deg - 10.0).abs() < 1e-5);
237:     assert!((gimbal.yaw_deg - 90.0).abs() < 1e-5);
238:     assert!((gimbal.yaw_360() - 90.0).abs() < 1e-5);
239:     assert!(gimbal.is_at_pitch_limit);
240:     assert!(!gimbal.is_at_roll_limit);
241:     assert!(!gimbal.is_at_yaw_limit);
242:     assert!(gimbal.is_at_any_limit());
243:     assert!(gimbal.is_stuck);
244:     assert_eq!(gimbal.mode, GimbalMode::Fpv);
245:     assert_eq!(gimbal.tilt_deg, None);
246: }
