135: impl HomeRecord {
136:     /// Parses a Home Point telemetry payload from a borrowed byte slice.
137:     ///
138:     /// # Errors
139:     /// Returns [`FlightReaderError::MalformedPayload`] if `payload.len() < 46`.
140:     pub fn parse(payload: &[u8]) -> Result<Self> {
141:         if payload.len() < MIN_HOME_PAYLOAD_LEN {
142:             return Err(FlightReaderError::MalformedPayload {
143:                 record_type: RECORD_TYPE,
144:                 reason: "Home payload shorter than 46 bytes",
145:             });
146:         }
147: 
148:         let lon_rad = LittleEndian::read_f64(&payload[0..8]);
149:         let lat_rad = LittleEndian::read_f64(&payload[8..16]);
150:         let height_raw = LittleEndian::read_f32(&payload[16..20]);
151:         let status_raw = LittleEndian::read_u16(&payload[20..22]);
152:         let go_home_height_m = LittleEndian::read_u16(&payload[22..24]);
153:         let course_lock_raw = LittleEndian::read_i16(&payload[24..26]);
154:         let data_recorder_file_index = LittleEndian::read_u16(&payload[30..32]);
155:         let force_landing_height_m = payload[45];
156: 
157:         Ok(Self {
158:             longitude_deg: lon_rad * RAD_TO_DEG,
159:             latitude_deg: lat_rad * RAD_TO_DEG,
160:             longitude_rad: lon_rad,
161:             latitude_rad: lat_rad,
162:             height_m: height_raw / 10.0,
163:             status: HomeStatusFlags::new(status_raw),
164:             go_home_height_m,
165:             course_lock_angle_deg: course_lock_raw as f64 / 10.0,
166:             data_recorder_file_index,
167:             force_landing_height_m,
168:         })
169:     }
