583: impl FlightRecordRecover {
584:     /// Parses a Record Type 50 crash recovery payload.
585:     pub fn parse(payload: &[u8]) -> Result<Self> {
586:         if payload.len() < RECOVER_MIN_LEN {
587:             return Err(FlightReaderError::TruncatedRecord {
588:                 expected: RECOVER_MIN_LEN,
589:                 available: payload.len(),
590:             });
591:         }
592: 
593:         let drone_type = payload[0];
594:         let app_type = payload[1];
595:         let app_version = if payload.len() >= 5 {
596:             [payload[2], payload[3], payload[4]]
597:         } else {
598:             [0, 0, 0]
599:         };
600: 
601:         let is_modern = payload.len() >= 109;
602: 
603:         let mut aircraft_serial = [0u8; 16];
604:         let mut aircraft_serial_len = 0u8;
605:         let mut aircraft_name = [0u8; 32];
606:         let mut aircraft_name_len = 0u8;
607:         let mut camera_serial = [0u8; 16];
608:         let mut camera_serial_len = 0u8;
609:         let mut rc_serial = [0u8; 16];
610:         let mut rc_serial_len = 0u8;
611:         let mut battery_serial = [0u8; 16];
612:         let mut battery_serial_len = 0u8;
613: 
614:         if is_modern {
615:             // Modern layout (v12+)
616:             if payload.len() >= 21 {
617:                 let slice = &payload[5..21.min(payload.len())];
618:                 aircraft_serial_len = Self::sanitize_alphanumeric(slice, &mut aircraft_serial);
619:             }
620:             if payload.len() >= 53 {
621:                 let slice = &payload[21..53.min(payload.len())];
622:                 aircraft_name_len = Self::sanitize_printable(slice, &mut aircraft_name);
623:             }
624:             if payload.len() >= 77 {
625:                 let slice = &payload[61..77.min(payload.len())];
626:                 camera_serial_len = Self::sanitize_alphanumeric(slice, &mut camera_serial);
627:             }
628:             if payload.len() >= 93 {
629:                 let slice = &payload[77..93.min(payload.len())];
630:                 rc_serial_len = Self::sanitize_alphanumeric(slice, &mut rc_serial);
631:             }
632:             if payload.len() >= 109 {
633:                 let slice = &payload[93..109.min(payload.len())];
634:                 battery_serial_len = Self::sanitize_battery_serial(slice, &mut battery_serial);
635:             }
636:         } else {
637:             // Legacy layout
638:             if payload.len() >= 15 {
639:                 let slice = &payload[5..15.min(payload.len())];
640:                 aircraft_serial_len = Self::sanitize_alphanumeric(slice, &mut aircraft_serial);
641:             }
642:             if payload.len() >= 39 {
643:                 let slice = &payload[15..39.min(payload.len())];
644:                 aircraft_name_len = Self::sanitize_printable(slice, &mut aircraft_name);
645:             }
646:             if payload.len() >= 65 {
647:                 let slice = &payload[55..65.min(payload.len())];
648:                 camera_serial_len = Self::sanitize_alphanumeric(slice, &mut camera_serial);
649:             }
650:             if payload.len() >= 75 {
651:                 let slice = &payload[65..75.min(payload.len())];
652:                 rc_serial_len = Self::sanitize_alphanumeric(slice, &mut rc_serial);
653:             }
654:             if payload.len() >= 85 {
655:                 let slice = &payload[75..85.min(payload.len())];
656:                 battery_serial_len = Self::sanitize_battery_serial(slice, &mut battery_serial);
657:             }
658:         }
659: 
660:         let gimbal_type = if payload.len() >= 110 {
661:             Some(payload[109])
662:         } else {
663:             None
664:         };
665: 
666:         Ok(Self {
667:             drone_type,
668:             app_type,
669:             app_version,
670:             aircraft_serial,
671:             aircraft_serial_len,
672:             aircraft_name,
673:             aircraft_name_len,
674:             camera_serial,
675:             camera_serial_len,
676:             rc_serial,
677:             rc_serial_len,
678:             battery_serial,
679:             battery_serial_len,
680:             gimbal_type,
681:             is_modern,
682:         })
683:     }
