685:     /// Filters and copies ASCII alphanumeric bytes into destination buffer.
686:     fn sanitize_alphanumeric(src: &[u8], dst: &mut [u8]) -> u8 {
687:         let mut count = 0usize;
688:         for &b in src {
689:             if count >= dst.len() {
690:                 break;
691:             }
692:             if b.is_ascii_alphanumeric() {
693:                 dst[count] = b;
694:                 count += 1;
695:             } else if b == 0 {
696:                 break;
697:             }
698:         }
699:         count as u8
700:     }
701: 
702:     /// Filters and copies printable ASCII bytes into destination buffer.
703:     fn sanitize_printable(src: &[u8], dst: &mut [u8]) -> u8 {
704:         let mut count = 0usize;
705:         for &b in src {
706:             if count >= dst.len() {
707:                 break;
708:             }
709:             if (0x20..=0x7E).contains(&b) {
710:                 dst[count] = b;
711:                 count += 1;
712:             } else if b == 0 {
713:                 break;
714:             }
715:         }
716:         count as u8
717:     }
718: 
719:     /// Sanitizes battery serial number, filtering out `"0000000000"`.
720:     fn sanitize_battery_serial(src: &[u8], dst: &mut [u8]) -> u8 {
721:         let len = Self::sanitize_alphanumeric(src, dst);
722:         let slice = &dst[..len as usize];
723:         if slice == b"0000000000" || slice.iter().all(|&b| b == b'0') {
724:             0
725:         } else {
726:             len
727:         }
728:     }
