//! Empirical Challenger verification test harness for Phase 2 Milestone 2.
//!
//! Validates:
//! 1. Bit-exact values against `tests/empirical/test_geodetic_telemetry_dat.py` lines 350-550
//! 2. Blackbox correlation join key: `data_recorder_file_index` -> `FLY{index:03}.DAT`
//! 3. Zero heap allocation in all `fn parse(payload: &[u8])` methods via custom GlobalAlloc
//! 4. Adversarial stress-testing, boundary condition fuzzing, and edge cases

use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};

use byteorder::{ByteOrder, LittleEndian};
use flightreader_core::error::FlightReaderError;
use flightreader_core::txt::records::{
    battery::{
        celsius_to_deci_kelvin, deci_kelvin_to_celsius, raw_current_to_amperes,
        smart_battery_alerts, BatteryCellVoltages, BatteryEnergySummary, BatteryRecord,
        FlightRecordRecover, PushedBatteryRecord, SmartBatteryGoHomeStatus, SmartBatteryGroup,
        TripodStateRecord, TripodStatus, MAX_BATTERY_CELLS, RECOVER_MIN_LEN,
        SENTINEL_UNINITIALIZED, SMART_BATTERY_GROUP_MIN_LEN, TRIPOD_STATE_MIN_LEN,
        VARIANT_A_MIN_LEN, VARIANT_B_MIN_LEN,
    },
    gimbal::{
        GimbalMode, GimbalRecord, EXTENDED_PAYLOAD_LEN as GIMBAL_EXTENDED_PAYLOAD_LEN,
        MIN_PAYLOAD_LEN as GIMBAL_MIN_PAYLOAD_LEN,
    },
    home::{HomeRecord, HomeStatusFlags, MIN_HOME_PAYLOAD_LEN},
    osd::{
        BatteryType, FlightAction, FlightMode, GoHomeStatus, GroundState, ModeChannel,
        OsdFlightStatus, OsdFlyState, OsdRecord, MIN_OSD_PAYLOAD_LEN,
    },
    rc::{
        is_stick_saturated, normalize_stick, normalize_stick_clamped, stick_percent, RcRecord,
        RcSwitchMode, MIN_PAYLOAD_LEN as RC_MIN_PAYLOAD_LEN,
        STANDARD_PAYLOAD_LEN as RC_STANDARD_PAYLOAD_LEN, STICK_CENTER, STICK_MAX, STICK_MIN,
    },
};

// ============================================================================
// ZERO HEAP ALLOCATION AUDIT HARNESS
// ============================================================================

struct CountingAllocator;

static ALLOC_COUNT: AtomicUsize = AtomicUsize::new(0);
static TRACKING_ENABLED: AtomicBool = AtomicBool::new(false);

unsafe impl GlobalAlloc for CountingAllocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        if TRACKING_ENABLED.load(Ordering::SeqCst) {
            ALLOC_COUNT.fetch_add(1, Ordering::SeqCst);
        }
        System.alloc(layout)
    }

    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) {
        System.dealloc(ptr, layout);
    }

    unsafe fn alloc_zeroed(&self, layout: Layout) -> *mut u8 {
        if TRACKING_ENABLED.load(Ordering::SeqCst) {
            ALLOC_COUNT.fetch_add(1, Ordering::SeqCst);
        }
        System.alloc_zeroed(layout)
    }

    unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, new_size: usize) -> *mut u8 {
        if TRACKING_ENABLED.load(Ordering::SeqCst) {
            ALLOC_COUNT.fetch_add(1, Ordering::SeqCst);
        }
        System.realloc(ptr, layout, new_size)
    }
}

#[global_allocator]
static GLOBAL: CountingAllocator = CountingAllocator;

fn assert_zero_alloc<F, R>(f: F) -> R
where
    F: FnOnce() -> R,
{
    ALLOC_COUNT.store(0, Ordering::SeqCst);
    TRACKING_ENABLED.store(true, Ordering::SeqCst);
    let result = f();
    TRACKING_ENABLED.store(false, Ordering::SeqCst);
    let allocations = ALLOC_COUNT.load(Ordering::SeqCst);
    assert_eq!(
        allocations, 0,
        "VIOLATION: Expected 0 heap allocations, but observed {allocations}"
    );
    result
}

// ============================================================================
// REQUIREMENT 1: BIT-EXACT VERIFICATION AGAINST test_geodetic_telemetry_dat.py
// ============================================================================

#[test]
fn test_req1_osd_telemetry_bit_exact_vectors() {
    // Exact parameters from test_geodetic_telemetry_dat.py lines 356-453
    let lon_deg = -122.419415f64;
    let lat_deg = 37.774929f64;
    let lon_rad = lon_deg.to_radians();
    let lat_rad = lat_deg.to_radians();

    let h_m = 125.4f64;
    let raw_h = (h_m * 10.0).round() as i16; // 1254
    let vx_ms = 8.5f64;
    let raw_vx = (vx_ms * 10.0).round() as i16; // 85
    let vy_ms = -4.2f64;
    let raw_vy = (vy_ms * 10.0).round() as i16; // -42
    let vz_ms = 1.8f64;
    let raw_vz = (vz_ms * 10.0).round() as i16; // 18
    let pitch_deg = 12.3f64;
    let raw_pitch = (pitch_deg * 10.0).round() as i16; // 123
    let roll_deg = -5.7f64;
    let raw_roll = (roll_deg * 10.0).round() as i16; // -57
    let yaw_deg = 145.8f64;
    let raw_yaw = (yaw_deg * 10.0).round() as i16; // 1458

    let byte30: u8 = (1 << 0) | (1 << 1) | (1 << 3) | (1 << 4) | (3 << 5); // 0x7B
    let flags32: u32 =
        (12 << 0) | (0 << 7) | (1 << 13) | (1 << 15) | (4 << 18) | (1 << 22);

    let flytime_sec = 234.5f64;
    let raw_flytime = (flytime_sec * 10.0).round() as u16; // 2345

    let mut osd_buf = [0u8; 55];
    LittleEndian::write_f64(&mut osd_buf[0..8], lon_rad);
    LittleEndian::write_f64(&mut osd_buf[8..16], lat_rad);
    LittleEndian::write_i16(&mut osd_buf[16..18], raw_h);
    LittleEndian::write_i16(&mut osd_buf[18..20], raw_vx);
    LittleEndian::write_i16(&mut osd_buf[20..22], raw_vy);
    LittleEndian::write_i16(&mut osd_buf[22..24], raw_vz);
    LittleEndian::write_i16(&mut osd_buf[24..26], raw_pitch);
    LittleEndian::write_i16(&mut osd_buf[26..28], raw_roll);
    LittleEndian::write_i16(&mut osd_buf[28..30], raw_yaw);
    osd_buf[30] = byte30;
    osd_buf[31] = 0x05; // FlyCCommand
    LittleEndian::write_u32(&mut osd_buf[32..36], flags32);
    osd_buf[36] = 18; // GpsNumber
    osd_buf[40] = 85; // Battery %
    LittleEndian::write_u16(&mut osd_buf[42..44], raw_flytime);

    let osd = OsdRecord::parse(&osd_buf).expect("OSD record parsing must succeed");

    // Kinematic & coordinate precision assertions
    assert!((osd.longitude_deg - lon_deg).abs() < 1e-6);
    assert!((osd.latitude_deg - lat_deg).abs() < 1e-6);
    assert!((osd.height_m - h_m).abs() < 1e-2);
    assert!((osd.relative_height() - h_m).abs() < 1e-2);
    assert!((osd.barometric_altitude() - h_m).abs() < 1e-2);

    // Velocities & climb rate
    assert!((osd.x_speed_mps - vx_ms).abs() < 1e-2);
    assert!((osd.y_speed_mps - vy_ms).abs() < 1e-2);
    assert!((osd.z_speed_mps - vz_ms).abs() < 1e-2);
    let expected_vh = (vx_ms.powi(2) + vy_ms.powi(2)).sqrt();
    let expected_v3d = (expected_vh.powi(2) + vz_ms.powi(2)).sqrt();
    assert!((osd.horizontal_speed() - expected_vh).abs() < 1e-4);
    assert!((osd.speed_3d() - expected_v3d).abs() < 1e-4);
    assert!((osd.vertical_climb_rate() - (-vz_ms)).abs() < 1e-2);
    assert!((osd.climb_rate() - (-vz_ms)).abs() < 1e-2);

    // Attitudes & heading
    assert!((osd.pitch_deg - pitch_deg).abs() < 1e-2);
    assert!((osd.roll_deg - roll_deg).abs() < 1e-2);
    assert!((osd.yaw_deg - yaw_deg).abs() < 1e-2);
    assert!((osd.yaw_360() - yaw_deg).abs() < 1e-2);

    // Byte 30 bitfields
    assert!(osd.fly_state.can_ioc_work());
    assert_eq!(osd.fly_state.ground_state(), GroundState::OnGround);
    assert!(osd.fly_state.is_motor_up());
    assert!(osd.fly_state.is_swave_work());
    assert_eq!(osd.fly_state.go_home_status(), GoHomeStatus::Cruising);

    // Bytes 32-35 status bitmask
    assert_eq!(osd.flight_status.flyc_state(), FlightMode::AutoLanding);
    assert!(osd.flight_status.is_failsafe_active()); // ACTIVE because bit 7 == 0
    assert_eq!(osd.flight_status.mode_channel(), 1);
    assert_eq!(osd.flight_status.mode_channel_enum(), ModeChannel::Sport);
    assert!(osd.flight_status.is_gps_used());
    assert_eq!(osd.flight_status.gps_level(), 4);
    assert_eq!(osd.flight_status.battery_type(), 1);
    assert_eq!(osd.flight_status.battery_type_enum(), BatteryType::Smart);

    // Discrete fields
    assert_eq!(osd.gps_satellite_count, 18);
    assert_eq!(osd.battery_percentage, 85);
    assert!((osd.fly_time_s - flytime_sec).abs() < 1e-2);
}

