#[test]
fn test_req1_battery_telemetry_bit_exact_vectors() {
    // Exact parameters from test_geodetic_telemetry_dat.py lines 486-522
    let temp_deg_c = 25.0f64;
    let raw_temp_k = celsius_to_deci_kelvin(temp_deg_c); // 2982 deci-K

    // Test Variant A: Energy Summary (< 34 bytes)
    let mut bat_a = [0u8; 16];
    bat_a[0] = 88; // RelativeCapacity %
    LittleEndian::write_u16(&mut bat_a[1..3], 15200); // 15.200 V
    LittleEndian::write_u16(&mut bat_a[3..5], 3800); // 3800 mAh
    LittleEndian::write_u16(&mut bat_a[5..7], 4500); // 4500 mAh
    bat_a[7] = 4; // Cell count
    LittleEndian::write_i16(&mut bat_a[8..10], raw_temp_k);

    let rec_a = BatteryRecord::parse(&bat_a).expect("Must parse Variant A");
    assert_eq!(rec_a.relative_capacity(), 88);
    assert!((rec_a.voltage() - 15.200).abs() < 1e-3);
    assert_eq!(rec_a.cell_count(), 4);
    assert!((rec_a.temperature_celsius() - 25.05).abs() < 0.1);

    // Test Variant B: Cell Voltages Array (34 bytes, num32 = 0)
    let mut bat_b = [0u8; 34];
    bat_b[0] = 88;
    LittleEndian::write_u16(&mut bat_b[1..3], 15200);
    for c in 0..4 {
        LittleEndian::write_u16(&mut bat_b[3 + c * 2..3 + c * 2 + 2], 3800);
    }
    bat_b[31] = 4; // Cell count
    LittleEndian::write_i16(&mut bat_b[32..34], raw_temp_k);

    let rec_b = BatteryRecord::parse(&bat_b).expect("Must parse Variant B");
    assert_eq!(rec_b.relative_capacity(), 88);
    assert!((rec_b.voltage() - 15.200).abs() < 1e-3);
    assert_eq!(rec_b.cell_count(), 4);
    assert!((rec_b.temperature_celsius() - 25.05).abs() < 0.1);

    if let BatteryRecord::CellVoltages(cv) = rec_b {
        assert_eq!(cv.num32, 0);
        assert_eq!(cv.cell_voltage(1), Some(3.800));
        assert_eq!(cv.cell_voltage(2), Some(3.800));
        assert_eq!(cv.cell_voltage(3), Some(3.800));
        assert_eq!(cv.cell_voltage(4), Some(3.800));
        assert_eq!(cv.cell_voltage(5), None);
        assert_eq!(cv.max_cell_voltage(), Some(3.800));
        assert_eq!(cv.min_cell_voltage(), Some(3.800));
        assert_eq!(cv.max_cell_deviation(), Some(0.0));
    } else {
        panic!("Expected Variant B CellVoltages");
    }

    // Current draw 2's complement conversion per ClsDjiLog.CalculateBatteryCurrent
    assert_eq!(raw_current_to_amperes(6000), 6.000); // <= 40A: no inversion
    assert_eq!(raw_current_to_amperes(40000), 40.000); // 40A boundary: no inversion
    assert!((raw_current_to_amperes(40001) - 25.535).abs() < 1e-3); // > 40A: (65536 - 40001)/1000 = 25.535
    assert!((raw_current_to_amperes(62000) - 3.536).abs() < 1e-3); // > 40A: (65536 - 62000)/1000 = 3.536
}

