#[test]
fn test_adversarial_truncation_matrix_exhaustive() {
    // Ensure all decoders cleanly return FlightReaderError on any truncation
    for len in 0..MIN_OSD_PAYLOAD_LEN {
        let buf = vec![0xAAu8; len];
        let err = OsdRecord::parse(&buf).unwrap_err();
        assert!(matches!(err, FlightReaderError::MalformedPayload { .. }));
    }

    for len in 0..MIN_HOME_PAYLOAD_LEN {
        let buf = vec![0xBBu8; len];
        let err = HomeRecord::parse(&buf).unwrap_err();
        assert!(matches!(err, FlightReaderError::MalformedPayload { .. }));
    }

    for len in 0..GIMBAL_MIN_PAYLOAD_LEN {
        let buf = vec![0xCCu8; len];
        let err = GimbalRecord::parse(&buf).unwrap_err();
        assert!(matches!(err, FlightReaderError::TruncatedRecord { .. }));
    }

    for len in 0..RC_MIN_PAYLOAD_LEN {
        let buf = vec![0xDDu8; len];
        let err = RcRecord::parse(&buf).unwrap_err();
        assert!(matches!(err, FlightReaderError::TruncatedRecord { .. }));
    }

    for len in 0..VARIANT_A_MIN_LEN {
        let buf = vec![0xEEu8; len];
        let err = BatteryEnergySummary::parse(&buf).unwrap_err();
        assert!(matches!(err, FlightReaderError::TruncatedRecord { .. }));
    }

    for len in 0..SMART_BATTERY_GROUP_MIN_LEN {
        let buf = vec![0xFFu8; len];
        let err = SmartBatteryGroup::parse(&buf).unwrap_err();
        assert!(matches!(err, FlightReaderError::TruncatedRecord { .. }));
    }

    assert!(TripodStateRecord::parse(&[]).is_err());

    for len in 0..RECOVER_MIN_LEN {
        let buf = vec![0x11u8; len];
        let err = FlightRecordRecover::parse(&buf).unwrap_err();
        assert!(matches!(err, FlightReaderError::TruncatedRecord { .. }));
    }
}

#[test]
fn test_adversarial_extreme_coordinates_and_yaw() {
    let mut buf = [0u8; 55];

    // Antimeridian crossing: 180.0 deg
    LittleEndian::write_f64(&mut buf[0..8], std::f64::consts::PI); // +180 deg
    LittleEndian::write_f64(&mut buf[8..16], -std::f64::consts::FRAC_PI_2); // -90 deg South Pole
    let osd = OsdRecord::parse(&buf).unwrap();
    assert!((osd.longitude_deg - 180.0).abs() < 1e-6);
    assert!((osd.latitude_deg - (-90.0)).abs() < 1e-6);
    assert!(osd.is_valid_coordinates());

    // Coordinate validation rejection: NaN / Inf / (0,0)
    let mut invalid_buf = [0u8; 55];
    LittleEndian::write_f64(&mut invalid_buf[0..8], f64::NAN);
    let osd_nan = OsdRecord::parse(&invalid_buf).unwrap();
    assert!(!osd_nan.is_valid_coordinates());

    let mut zero_coord_buf = [0u8; 55];
    let osd_zero = OsdRecord::parse(&zero_coord_buf).unwrap();
    assert!(!osd_zero.is_valid_coordinates());

    // Negative Yaw normalization in Gimbal and OSD
    LittleEndian::write_i16(&mut buf[28..30], -1800); // -180.0 deg
    let osd_neg_yaw = OsdRecord::parse(&buf).unwrap();
    assert_eq!(osd_neg_yaw.yaw_deg, -180.0);
    assert_eq!(osd_neg_yaw.yaw_360(), 180.0);

    let gimbal_buf = [0u8, 0u8, 0u8, 0u8, 0xF6, 0xF8, 0u8]; // raw_yaw = -1802 -> -180.2 deg
    let g = GimbalRecord::parse(&gimbal_buf).unwrap();
    assert!((g.yaw_360() - (360.0 - 180.2)).abs() < 1e-5);
}

#[test]
fn test_adversarial_battery_cell_saturation_and_sentinels() {
    // 34 bytes (num32 = 0), cell count specified as 255 (must clamp to 14 without OOB)
    let mut buf = [0u8; 34];
    buf[31] = 255; // Extreme cell count
    for c in 0..14 {
        LittleEndian::write_u16(&mut buf[3 + c * 2..3 + c * 2 + 2], 4200);
    }
    let rec = BatteryCellVoltages::parse(&buf).unwrap();
    assert_eq!(rec.cell_count, MAX_BATTERY_CELLS as u8);
    for i in 1..=14 {
        assert_eq!(rec.cell_voltage(i), Some(4.200));
    }
    assert_eq!(rec.cell_voltage(15), None);

    // Unequipped cells (0 or 0xFFFF)
    let mut buf_unequipped = [0u8; 34];
    buf_unequipped[31] = 4;
    LittleEndian::write_u16(&mut buf_unequipped[3..5], 3700);
    LittleEndian::write_u16(&mut buf_unequipped[5..7], 0); // zero mV -> uninitialized
    LittleEndian::write_u16(&mut buf_unequipped[7..9], 0xFFFF); // 0xFFFF -> uninitialized
    LittleEndian::write_u16(&mut buf_unequipped[9..11], 3750);
    let rec_un = BatteryCellVoltages::parse(&buf_unequipped).unwrap();
    assert_eq!(rec_un.cell_voltage(1), Some(3.700));
    assert_eq!(rec_un.cell_voltage(2), None);
    assert_eq!(rec_un.cell_voltage(3), None);
    assert_eq!(rec_un.cell_voltage(4), Some(3.750));
    assert_eq!(rec_un.max_cell_voltage(), Some(3.750));
    assert_eq!(rec_un.min_cell_voltage(), Some(3.700));
    assert!((rec_un.max_cell_deviation().unwrap() - 0.050).abs() < 1e-4);
}

#[test]
fn test_adversarial_unmapped_enums_never_panic() {
    // Test that unexpected hardware enum values cleanly map to Other/Unknown without panic
    assert_eq!(GroundState::from_bits(3), GroundState::Unknown);
    assert_eq!(GoHomeStatus::from_bits(7), GoHomeStatus::Other(7));
    assert_eq!(FlightMode::from_u8(250), FlightMode::Other(250));
    assert_eq!(ModeChannel::from_bits(3), ModeChannel::Unknown(3));
    assert_eq!(BatteryType::from_bits(3), BatteryType::Unknown(3));
    assert_eq!(FlightAction::from_u8(99), FlightAction::Other(99));
    assert_eq!(GimbalMode::from_bits(3), GimbalMode::Unknown(3));
    assert_eq!(RcSwitchMode::from_bits(3), RcSwitchMode::Position3);
    assert_eq!(TripodStatus::Other(99), TripodStatus::Other(99));
}

