use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicI32, AtomicUsize, Ordering};

use byteorder::{ByteOrder, LittleEndian};
use flightreader_core::error::FlightReaderError;
use flightreader_core::txt::records::{
    battery::{
        celsius_to_deci_kelvin, raw_current_to_amperes, BatteryCellVoltages, BatteryEnergySummary,
        BatteryRecord, FlightRecordRecover, PushedBatteryRecord, SmartBatteryGroup,
        TripodStateRecord, TripodStatus, MAX_BATTERY_CELLS, RECOVER_MIN_LEN,
        SMART_BATTERY_GROUP_MIN_LEN, VARIANT_A_MIN_LEN,
    },
    gimbal::{GimbalMode, GimbalRecord, MIN_PAYLOAD_LEN as GIMBAL_MIN_PAYLOAD_LEN},
    home::{HomeRecord, MIN_HOME_PAYLOAD_LEN},
    osd::{
        BatteryType, FlightAction, FlightMode, GoHomeStatus, GroundState, ModeChannel,
        OsdRecord, MIN_OSD_PAYLOAD_LEN,
    },
    rc::{
        normalize_stick, stick_percent, RcRecord, RcSwitchMode,
        MIN_PAYLOAD_LEN as RC_MIN_PAYLOAD_LEN,
    },
};

// ============================================================================
// ZERO HEAP ALLOCATION AUDIT HARNESS
// ============================================================================

extern "C" {
    fn gettid() -> i32;
}

struct CountingAllocator;

static ALLOC_COUNT: AtomicUsize = AtomicUsize::new(0);
static TRACKED_TID: AtomicI32 = AtomicI32::new(0);

unsafe impl GlobalAlloc for CountingAllocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        let tid = gettid();
        if TRACKED_TID.load(Ordering::Relaxed) == tid {
            ALLOC_COUNT.fetch_add(1, Ordering::Relaxed);
        }
        System.alloc(layout)
    }

    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) {
        System.dealloc(ptr, layout);
    }

    unsafe fn alloc_zeroed(&self, layout: Layout) -> *mut u8 {
        let tid = gettid();
        if TRACKED_TID.load(Ordering::Relaxed) == tid {
            ALLOC_COUNT.fetch_add(1, Ordering::Relaxed);
        }
        System.alloc_zeroed(layout)
    }

    unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, new_size: usize) -> *mut u8 {
        let tid = gettid();
        if TRACKED_TID.load(Ordering::Relaxed) == tid {
            ALLOC_COUNT.fetch_add(1, Ordering::Relaxed);
        }
        System.realloc(ptr, layout, new_size)
    }
}

#[global_allocator]
static GLOBAL: CountingAllocator = CountingAllocator;

fn assert_zero_alloc<F, R>(f: F) -> R
where
    F: FnOnce() -> R,
{
    let tid = unsafe { gettid() };
    ALLOC_COUNT.store(0, Ordering::SeqCst);
    TRACKED_TID.store(tid, Ordering::SeqCst);
    let result = f();
    TRACKED_TID.store(0, Ordering::SeqCst);
    let allocations = ALLOC_COUNT.load(Ordering::SeqCst);
    assert_eq!(
        allocations, 0,
        "VIOLATION: Expected 0 heap allocations, but observed {allocations}"
    );
    result
}

