#[test]
fn test_adversarial_unmapped_enums_never_panic() {
    // Test that unexpected hardware enum values cleanly map to Other/Unknown without panic
    assert_eq!(GroundState::from_bits(3), GroundState::Unknown);
    assert_eq!(GoHomeStatus::from_bits(7), GoHomeStatus::Other(7));
    assert_eq!(FlightMode::from_u8(250), FlightMode::Other(250));
    assert_eq!(ModeChannel::from_bits(3), ModeChannel::Unknown(3));
    assert_eq!(BatteryType::from_bits(3), BatteryType::Unknown(3));
    assert_eq!(FlightAction::from_u8(99), FlightAction::Other(99));
    assert_eq!(GimbalMode::from_bits(3), GimbalMode::Unknown(3));
    assert_eq!(RcSwitchMode::from_bits(3), RcSwitchMode::Position3);
    assert_eq!(TripodStatus::Other(99), TripodStatus::Other(99));
}

#[test]
fn test_osd_flight_status_bitfields_comprehensive() {
    let mut payload = [0u8; 55];
    let bitmask: u32 = (1 << 8)    // is_vision_used
        | (3 << 9)                 // voltage_warning = 3
        | (1 << 12)                // is_imu_preheated
        | (1 << 16)                // is_compass_error
        | (1 << 17)                // is_wave_error
        | (1 << 24)                // is_accelerometer_over_range
        | (1 << 25)                // is_vibrating
        | (1 << 26)                // is_barometer_dead_in_air
        | (1 << 27)                // is_not_enough_force
        | (1 << 28)                // is_motor_blocked
        | (1 << 29)                // is_propeller_catapult
        | (1 << 30)                // is_go_home_height_modified
        | (1 << 31);               // is_out_of_limit

    LittleEndian::write_u32(&mut payload[32..36], bitmask);
    payload[37] = 2; // flight_action: AutoLanding

    let osd = OsdRecord::parse(&payload).unwrap();
    let fs = osd.flight_status;

    assert!(fs.is_vision_used());
    assert_eq!(fs.voltage_warning(), 3);
    assert!(fs.is_imu_preheated());
    assert!(fs.is_compass_error());
    assert!(fs.is_wave_error());
    assert!(fs.is_accelerometer_over_range());
    assert!(fs.is_accelerator_over_range());
    assert!(fs.is_vibrating());
    assert!(fs.is_barometer_dead_in_air());
    assert!(fs.is_not_enough_force());
    assert!(fs.is_motor_blocked());
    assert!(fs.is_propeller_catapult());
    assert!(fs.is_go_home_height_modified());
    assert!(fs.is_out_of_limit());
    assert_eq!(osd.flight_action_enum(), FlightAction::AutoLanding);
}

#[test]
fn test_home_status_flags_comprehensive() {
    let mut payload = [0u8; 50];
    let raw_flags: u16 = (1 << 0)   // is_home_record
        | (1 << 1)                  // go_home_mode = 1
        | (1 << 2)                  // aircraft_head_direction = 1
        | (1 << 3)                  // is_dynamic_home_point_enabled
        | (1 << 4)                  // is_reach_limit_distance
        | (1 << 5)                  // is_reach_limit_height
        | (1 << 6)                  // is_multiple_flight_mode_enabled
        | (2 << 8)                  // compass_ceiling_status = 2
        | (1 << 10)                 // is_compass_ceiling
        | (1 << 11)                 // is_beginner_mode
        | (1 << 12)                 // is_ioc
        | (3 << 13);                // ioc_mode = 3

    LittleEndian::write_u16(&mut payload[20..22], raw_flags);
    let home = HomeRecord::parse(&payload).unwrap();
    let s = home.status;

    assert!(s.is_home_record());
    assert_eq!(s.go_home_mode(), 1);
    assert_eq!(s.aircraft_head_direction(), 1);
    assert!(s.is_dynamic_home_point_enabled());
    assert!(s.is_reach_limit_distance());
    assert!(s.is_reach_limit_height());
    assert!(s.is_multiple_flight_mode_enabled());
    assert_eq!(s.compass_ceiling_status(), 2);
    assert!(s.is_compass_ceiling());
    assert!(s.is_beginner_mode());
    assert!(s.is_ioc());
    assert_eq!(s.ioc_mode(), 3);
}

